# Builds target\installer\audiomon-setup-<version>.exe:
#   1. release build of the tray app (embeds the icon generated by crates\host\build.rs),
#   2. stages that icon for the setup wizard,
#   3. compiles installer\audiomon.iss with Inno Setup 6.
# Usage (from anywhere): powershell -File installer\build.ps1

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
Set-Location $root

$version = (Select-String -Path Cargo.toml -Pattern '^version\s*=\s*"([^"]+)"').Matches[0].Groups[1].Value
Write-Host "audiomon $version"

cargo build --release -p audiomon-host
if ($LASTEXITCODE -ne 0) { throw "cargo build failed" }

$out = Join-Path $root "target\installer"
New-Item -ItemType Directory -Force $out | Out-Null
$icon = Get-ChildItem "target\release\build\audiomon-host-*\out\audiomon.ico" |
    Sort-Object LastWriteTime -Descending | Select-Object -First 1
if (-not $icon) { throw "generated icon not found; did build.rs run?" }
Copy-Item $icon.FullName (Join-Path $out "audiomon.ico") -Force

$iscc = @(
    "$env:LOCALAPPDATA\Programs\Inno Setup 6\ISCC.exe",
    "${env:ProgramFiles(x86)}\Inno Setup 6\ISCC.exe",
    "$env:ProgramFiles\Inno Setup 6\ISCC.exe"
) | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $iscc) { throw "Inno Setup 6 not found (winget install JRSoftware.InnoSetup)" }

& $iscc /Qp "/DAppVersion=$version" installer\audiomon.iss
if ($LASTEXITCODE -ne 0) { throw "Inno Setup failed" }
Get-Item (Join-Path $out "audiomon-setup-$version.exe")
